1	package filter
2	
3	import (
4		"context"
5		"strings"
6		"sync"
7		"time"
8	
9		"github.com/google/cel-go/cel"
10		"github.com/pkg/errors"
11	)
12	
13	// Engine parses CEL filters into a dialect-agnostic condition tree.
14	type Engine struct {
15		schema Schema
16		env    *cel.Env
17		// nowFunc resolves the value of the `now` variable. It is frozen once per
18		// Compile so a single filter sees a single instant, and is overridable in
19		// tests for deterministic folding.
20		nowFunc func() time.Time
21	}
22	
23	// NewEngine builds a new Engine for the provided schema.
24	func NewEngine(schema Schema) (*Engine, error) {
25		env, err := cel.NewEnv(schema.EnvOptions...)
26		if err != nil {
27			return nil, errors.Wrap(err, "failed to create CEL environment")
28		}
29		return &Engine{
30			schema:  schema,
31			env:     env,
32			nowFunc: time.Now,
33		}, nil
34	}
35	
36	// Program stores a compiled filter condition.
37	type Program struct {
38		schema    Schema
39		condition Condition
40	}
41	
42	// ConditionTree exposes the underlying condition tree.
43	func (p *Program) ConditionTree() Condition {
44		return p.condition
45	}
46	
47	// Compile parses the filter string into an executable program.
48	func (e *Engine) Compile(_ context.Context, filter string) (*Program, error) {
49		if strings.TrimSpace(filter) == "" {
50			return nil, errors.New("filter expression is empty")
51		}
52	
53		ast, issues := e.env.Compile(filter)
54		if issues != nil && issues.Err() != nil {
55			return nil, errors.Wrap(issues.Err(), "failed to compile filter")
56		}
57		parsed, err := cel.AstToParsedExpr(ast)
58		if err != nil {
59			return nil, errors.Wrap(err, "failed to convert AST")
60		}
61	
62		cond, err := buildCondition(parsed.GetExpr(), parseContext{schema: e.schema, now: e.nowFunc()})
63		if err != nil {
64			return nil, err
65		}
66	
67		return &Program{
68			schema:    e.schema,
69			condition: cond,
70		}, nil
71	}
72	
73	// CompileToStatement compiles and renders the filter in a single step.
74	func (e *Engine) CompileToStatement(ctx context.Context, filter string, opts RenderOptions) (Statement, error) {
75		program, err := e.Compile(ctx, filter)
76		if err != nil {
77			return Statement{}, err
78		}
79		return program.Render(opts)
80	}
81	
82	// RenderOptions configure SQL rendering.
83	type RenderOptions struct {
84		Dialect           DialectName
85		PlaceholderOffset int
86		DisableNullChecks bool
87	}
88	
89	// Statement contains the rendered SQL fragment and its args.
90	type Statement struct {
91		SQL  string
92		Args []any
93	}
94	
95	// Render converts the program into a dialect-specific SQL fragment.
96	func (p *Program) Render(opts RenderOptions) (Statement, error) {
97		renderer := newRenderer(p.schema, opts)
98		return renderer.Render(p.condition)
99	}
100	
101	var (
102		defaultOnce           sync.Once
103		defaultInst           *Engine
104		defaultErr            error
105		defaultAttachmentOnce sync.Once
106		defaultAttachmentInst *Engine
107		defaultAttachmentErr  error
108	)
109	
110	// DefaultEngine returns the process-wide memo filter engine.
111	func DefaultEngine() (*Engine, error) {
112		defaultOnce.Do(func() {
113			defaultInst, defaultErr = NewEngine(NewSchema())
114		})
115		return defaultInst, defaultErr
116	}
117	
118	// DefaultAttachmentEngine returns the process-wide attachment filter engine.
119	func DefaultAttachmentEngine() (*Engine, error) {
120		defaultAttachmentOnce.Do(func() {
121			defaultAttachmentInst, defaultAttachmentErr = NewEngine(NewAttachmentSchema())
122		})
123		return defaultAttachmentInst, defaultAttachmentErr
124	}
